package com.gameaggregator.apikeyservice.application;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.HexFormat;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;@Component public class ApiKeyHasher{final byte[] pepper;public ApiKeyHasher(@Value("${api-key.pepper}")String p){if(p.length()<32)throw new IllegalStateException("API key pepper must have at least 32 characters");pepper=p.getBytes(StandardCharsets.UTF_8);}public String hash(String raw){try{var d=MessageDigest.getInstance("SHA-256");d.update(pepper);return HexFormat.of().formatHex(d.digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}}